INSERT INTO repair_tickets (request_id, title, description, department, location, requester_name, requester_phone, priority, status, technician_name, repair_result, remark, request_image_url, created_at) VALUES
('REP-202609-001', 'เครื่องปรับอากาศมีน้ำหยดและไม่เย็น', 'แอร์ห้องนอนวิลล่ามีน้ำหยดลงพื้น เตียงเปียก และพัดลมแอร์มีเสียงดัง', 'ห้องพัก & วิลล่า', 'วิลล่า 104 (โซนบ้านแกะ)', 'คุณกรรณิการ์ (แม่บ้าน)', '089-111-2233', 'critical', 'pending', NULL, NULL, 'ลูกค้าพักต่อเนื่อง รีเควสท์เข้าซ่อมด่วน', 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=600', NOW() - INTERVAL '4 days 8 hours'),
('REP-202609-002', 'สปริงเกอร์รดน้ำแปลงหญ้าแกะไม่หมุนและน้ำรั่ว', 'หัวสปริงเกอร์ตัวที่ 3 แตก ท่อหลุด น้ำพุ่งกระจาย สัตว์กินหญ้าไม่ได้', 'ฟาร์มสัตว์ & กิจกรรม', 'แปลงหญ้าโซนป้อนอาหาร 2', 'คุณสมพงษ์ (ดูแลฟาร์ม)', '089-222-3344', 'high', 'waiting_parts', 'ช่างประสิทธิ์ (ประปา/สุขาภิบาล)', 'ตรวจพบเกลียวท่อ PVC 1 นิ้วแตก รอนำข้อต่อใหม่มาสวม', 'สั่งอะไหล่แล้ว คาดว่าเข้าช่วงบ่าย', NULL, NOW() - INTERVAL '3 days 14 hours'),
('REP-202609-003', 'เครื่องชงกาแฟ Espresso แรงดันตก น้ำไม่ไหล', 'หัวชงฝั่งขวาน้ำไม่ออก เกจแรงดันนิ่ง มีกลิ่นไหม้เล็กน้อย', 'คาเฟ่ & F&B', 'Scenery Cafe ชั้น 1', 'คุณแนน (บาริสต้า)', '089-333-4455', 'critical', 'in_progress', 'ช่างวิชัย (ไฟฟ้า/แอร์)', 'กำลังถอดล้างตะกรันและเช็ควาล์วขดลวดแม่เหล็ก', 'เตรียมอะไหล่สำรองพร้อมเปลี่ยน', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600', NOW() - INTERVAL '2 days 5 hours'),
('REP-202609-004', 'ไฟกิ่งทางเดินมืด ดับ 3 ต้นติดกัน', 'ไฟกิ่งหมายเลข L12, L13, L14 ไม่ติด ทางเดินมืดอันตรายต่อแขก', 'ไฟฟ้า & แอร์', 'ทางเดินล็อบบี้ไปห้องอาหาร', 'รปภ. ประเสริฐ', '089-444-5566', 'high', 'pending', NULL, NULL, 'เบรกเกอร์ทริปช่วงฝนตก ต้องเช็คสายไฟรั่ว', NULL, NOW() - INTERVAL '1 day 10 hours'),
('REP-202609-005', 'ประตูบานเลื่อนห้องน้ำปิดไม่สนิท ลูกล้อตกราง', 'รางประตูด้านบนหลุด แขกเลื่อนเปิดปิดยาก เสี่ยงหลุดหล่น', 'ซ่อมบำรุงอาคาร & สี', 'ห้องน้ำชาย ฝั่งลานกิจกรรม', 'คุณวรรณา (แม่บ้าน)', '089-555-6677', 'normal', 'assigned', 'ช่างเอกชัย (อาคาร/สี)', NULL, 'เตรียมน็อตและลูกล้อรางแขวนเข้าแก้ไข', NULL, NOW() - INTERVAL '18 hours'),
('REP-202609-006', 'เครื่องปริ้นใบเสร็จแคชเชียร์สัญญาณไม่เข้า', 'สายแลนไฟไม่กระพริบ ปริ้นตั๋วให้ลูกค้าไม่ได้ ต้องเขียนมือแทน', 'ไอที & ระบบสื่อสาร', 'จุดขายบัตรทางเข้าฟาร์ม', 'แคชเชียร์ 01', '089-666-7788', 'critical', 'pending', NULL, NULL, 'เร่งด่วน คนรอคิวเข้าชมฟาร์มเยอะ', NULL, NOW() - INTERVAL '3 hours'),
('REP-202609-007', 'รถรางบริการนักท่องเที่ยวคันที่ 2 สตาร์ทติดยาก', 'มีเสียงไดสตาร์ทฟรี แบตเตอรี่เริ่มอ่อนเวลาจอดข้ามคืน', 'รถบริการ & ยานพาหนะ', 'จุดจอดรถรางหลัก', 'คนขับ ธวัชชัย', '089-777-8899', 'normal', 'pending', NULL, NULL, 'นำเข้าโรงซ่อมช่วงเย็นหลังหมดรอบบริการ', NULL, NOW() - INTERVAL '1 hour'),
('REP-202609-008', 'เปลี่ยนหลอดไฟดาวน์ไลท์ห้องน้ำแขก', 'หลอดไฟ LED ขั้ว E27 ขาด สว่างดวงเดียว', 'ห้องพัก & วิลล่า', 'วิลล่า 101', 'คุณกรรณิการ์', '089-111-2233', 'low', 'completed', 'ช่างวิชัย (ไฟฟ้า/แอร์)', 'เปลี่ยนหลอด LED 9W Warm White ดวงใหม่ ทดสอบเปิดติดสว่างปกติ', 'ปิดงานเรียบร้อย', NULL, NOW() - INTERVAL '6 days')
